(function(PF){
'use strict';
const statuses={todo:'To do',doing:'In progress',done:'Done'},requestStatuses={new:'New',progress:'In progress',review:'In review',done:'Done'},priorities={low:'Low',normal:'Normal',high:'High'};
const state={tasks:{mode:'board',status:'',priority:'',project:'',assignee:''},requests:{mode:'list',status:'',priority:'',project:'',assignee:'',client:''},client:''};
const pairs=obj=>Object.entries(obj), text=(v,max=500,required=false)=>{if(typeof v!=='string'||v.length>max||(required&&!v.trim()))throw Error('Complete the required fields within the character limits.');return v.trim()};
function due(v){if(typeof v!=='string'||(v&&!/^\d{4}-\d{2}-\d{2}$/.test(v)))throw Error('Enter a valid due date.');if(v){const d=new Date(v+'T12:00:00Z');if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==v)throw Error('Enter a valid due date.')}return v}
function choice(value,options){if(!Object.hasOwn(options,value))throw Error('Choose a valid option.');return value}
function task(id){const t=PF.w.tasks.find(x=>x.id===id);if(!t)throw Error('Task no longer exists.');return t}
function request(id){const r=PF.db.requests.find(x=>x.id===id);if(!r)throw Error('Request no longer exists.');return r}
const defaultMeta=()=>({status:'new',priority:'normal',assignee:'',due:'',projectId:''});
const meta=id=>PF.w.requestMeta[id]||defaultMeta();
function projectId(id,clientId){if(!id)return '';const p=PF.project(id);if(!p||(clientId&&p.clientId!==clientId))throw Error('Choose a project belonging to this client.');return id}
function scopedClient(id){if(!PF.client(id))throw Error('Client no longer exists.');return id}
function options(opts,value){return opts.map(([v,label])=>`<option value="${PF.e(v)}" ${v===value?'selected':''}>${PF.e(label)}</option>`).join('')}
function select(name,label,opts,value,attrs=''){return `<label>${PF.e(label)}<select name="${PF.e(name)}" aria-label="${PF.e(label)}" ${attrs}>${options(opts,value)}</select></label>`}
function field(name,label,value='',type='text',required=false){return `<label>${PF.e(label)}<input name="${name}" type="${type}" value="${PF.e(value)}" maxlength="500" ${required?'required':''}></label>`}
function area(name,label,value='',required=false){return `<label>${PF.e(label)}<textarea name="${name}" maxlength="4000" ${required?'required':''}>${PF.e(value)}</textarea></label>`}
function filter(kind,key,label,opts){return select(key,label,[['','All '+label.toLowerCase()],...opts],state[kind][key],`data-pf-filter="${kind}" data-key="${key}"`)}
function activeFilters(kind){return Object.entries(state[kind]).some(([key,value])=>key!=='mode'&&value!=='')}
function controls(kind,count,total){const s=state[kind],choices=kind==='tasks'?statuses:requestStatuses;const names=[...new Set((kind==='tasks'?PF.w.tasks:PF.db.requests.map(r=>meta(r.id))).map(x=>x.assignee).filter(Boolean))].sort();return `<div class="card actions pf-filters" style="margin-bottom:18px">${filter(kind,'status','Status',pairs(choices))}${filter(kind,'priority','Priority',pairs(priorities))}${filter(kind,'project','Project',PF.projectOptions())}${filter(kind,'assignee','Assignee',names.map(x=>[x,x]))}${kind==='requests'?filter(kind,'client','Client',PF.clientOptions()):''}${select('mode','View',[['list','List'],['board','Kanban']],s.mode,`data-pf-filter="${kind}" data-key="mode"`)}<span class="meta" role="status">${count} of ${total} ${kind}</span>${activeFilters(kind)?PF.button('Clear filters','pf-clear-filters',kind):''}</div>`}
function matches(kind,row,clientId){const s=state[kind];return (!s.status||row.status===s.status)&&(!s.priority||row.priority===s.priority)&&(!s.project||row.projectId===s.project)&&(!s.assignee||row.assignee===s.assignee)&&(!s.client||s.client===clientId)}
function move(kind,row){return select('status','Move to',pairs(kind==='tasks'?statuses:requestStatuses),row.status,`data-pf-move="${kind}" data-id="${PF.e(row.id)}"`)}
function taskCard(t){return `<article class="card" style="margin-bottom:12px"><h3>${PF.e(t.title)}</h3><p class="meta">${PF.e(PF.project(t.projectId)?.name||'No project')} · ${PF.e(priorities[t.priority])} priority · ${PF.e(t.assignee||'Unassigned')} · ${PF.e(PF.date(t.due))}</p><span class="badge">${PF.e(statuses[t.status])}</span>${t.checklist.length?`<div class="list" style="margin:12px 0">${t.checklist.map(c=>`<div class="actions">${PF.button(c.done?'✓ Done':'Mark done','pf-toggle-check',t.id).replace('data-id=',`data-item="${PF.e(c.id)}" data-id=`)}<span>${PF.e(c.text)}</span></div>`).join('')}</div>`:''}<div class="actions">${PF.button('Edit task','pf-edit-task',t.id)}${move('tasks',t)}</div></article>`}
function requestCard(r){const m=meta(r.id);return `<article class="card" style="margin-bottom:12px"><h3>${PF.e(r.title)}</h3><p class="preserve-lines">${PF.e(r.note)}</p><p class="meta">${PF.e(PF.client(r.clientId)?.name)} · ${PF.e(PF.project(m.projectId)?.name||'No project')} · ${PF.e(priorities[m.priority])} priority · ${PF.e(m.assignee||'Unassigned')} · ${PF.e(PF.date(m.due))}</p><span class="badge">${PF.e(requestStatuses[m.status])}</span><div class="actions" style="margin-top:12px">${PF.button('Edit workflow','pf-edit-request',r.id)}${move('requests',{...m,id:r.id})}</div></article>`}
function layout(kind,rows,render,total){if(!rows.length)return PF.empty(total?'No matching '+kind+'. Clear filters to see all '+kind+'.':kind==='tasks'?'No tasks yet. Add a task to plan your work.':'No requests yet. Add a request to track client inputs.');if(state[kind].mode==='list')return `<div class="list">${rows.map(render).join('')}</div>`;const choices=kind==='tasks'?statuses:requestStatuses;return `<div class="pf-kanban" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px;align-items:start">${pairs(choices).map(([key,label])=>{const group=rows.filter(x=>(kind==='tasks'?x:meta(x.id)).status===key);return `<section><h2>${PF.e(label)} <span class="meta">${group.length}</span></h2>${group.map(render).join('')||PF.empty('No items')}</section>`}).join('')}</div>`}
PF.views.tasks={title:'Tasks',icon:'▦',group:'work',render(){const rows=PF.w.tasks.filter(t=>matches('tasks',t)),total=PF.w.tasks.length;return PF.heading('Tasks','Plan work and track checklists. Saved only in this browser.',PF.button('+ New task','pf-add-task','',true))+controls('tasks',rows.length,total)+layout('tasks',rows,taskCard,total)}};
PF.views.requests={title:'Requests',icon:'⇥',group:'work',render(){const rows=PF.db.requests.filter(r=>matches('requests',meta(r.id),r.clientId)),total=PF.db.requests.length;return PF.heading('Requests','Client inputs, assignments, and review stages. Local demo only.',PF.button('+ New request','pf-add-request','',true))+controls('requests',rows.length,total)+layout('requests',rows,requestCard,total)}};
PF.actions['pf-clear-filters']=b=>{const kind=b.dataset.id;if(kind!=='tasks'&&kind!=='requests')return;Object.keys(state[kind]).forEach(key=>{if(key!=='mode')state[kind][key]=''});PF.render()};
function taskForm(id='',preset=''){const current=id?task(id):null;PF.form(current?'Edit task':'New task',field('title','Task title',current?.title||'','text',true)+select('projectId','Project',[['','No project'],...PF.projectOptions()],current?.projectId||preset)+select('status','Status',pairs(statuses),current?.status||'todo')+select('priority','Priority',pairs(priorities),current?.priority||'normal')+field('assignee','Assignee',current?.assignee||'')+field('due','Due date',current?.due||'','date')+area('checklist','Checklist — one item per line',current?.checklist.map(c=>c.text).join('\n')||''),f=>{const target=id?task(id):null;const lines=text(f.checklist,4000).split(/\r?\n/).map(s=>s.trim()).filter(Boolean);if(lines.length>50||lines.some(x=>x.length>500))throw Error('Use up to 50 checklist items, each under 500 characters.');const old=(target?.checklist||[]).slice();const checklist=lines.map(line=>{const index=old.findIndex(c=>c.text===line);return index>=0?old.splice(index,1)[0]:{id:PF.id(),text:line,done:false}});const value={title:text(f.title,500,true),projectId:projectId(f.projectId),status:choice(f.status,statuses),priority:choice(f.priority,priorities),assignee:text(f.assignee),due:due(f.due),checklist};if(target)Object.assign(target,value);else PF.w.tasks.push({id:PF.id(),...value});PF.log('task',target?'Task updated':'Task created',value.projectId)})}
PF.actions['pf-add-task']=b=>taskForm('',b.dataset.id||'');PF.actions['pf-edit-task']=b=>taskForm(b.dataset.id);
PF.actions['pf-toggle-check']=b=>PF.change(()=>{const t=task(b.dataset.id),c=t.checklist.find(x=>x.id===b.dataset.item);if(!c)throw Error('Checklist item no longer exists.');c.done=!c.done;PF.log('task','Checklist updated',t.projectId)});
PF.actions['pf-edit-request']=b=>{const r=request(b.dataset.id),m=meta(r.id);PF.form('Request workflow',select('status','Status',pairs(requestStatuses),m.status)+select('priority','Priority',pairs(priorities),m.priority)+field('assignee','Assignee',m.assignee)+field('due','Due date',m.due,'date')+select('projectId','Client project',[['','No project'],...PF.db.projects.filter(p=>p.clientId===r.clientId).map(p=>[p.id,p.name])],m.projectId),f=>{const live=request(b.dataset.id);PF.w.requestMeta[live.id]={status:choice(f.status,requestStatuses),priority:choice(f.priority,priorities),assignee:text(f.assignee),due:due(f.due),projectId:projectId(f.projectId,live.clientId)};PF.log('request','Request workflow updated',f.projectId,live.clientId)})};
PF.actions['pf-add-request']=b=>{if(!PF.db.clients.length){PF.toast('Create a client first.');return}PF.form('New local client request',select('clientId','Client',PF.clientOptions(),b.dataset.id||PF.db.clients[0].id)+field('title','Subject','','text',true)+area('note','Request / content / notes','',true),f=>{const clientId=scopedClient(f.clientId),id=PF.id();PF.db.requests.push({id,clientId,title:text(f.title,500,true),note:text(f.note,4000,true),createdAt:PF.now()});PF.w.requestMeta[id]=defaultMeta();PF.log('request','Client request created','',clientId)})};
function thread(c){const messages=PF.w.messages.filter(m=>m.clientId===c.id);return `<section class="card" style="margin-top:18px"><div class="row"><h2>Messages</h2>${PF.button('+ Write message','pf-add-message',c.id)}</div><p class="meta">Local conversation simulation. Messages are not delivered. “Client preview” simulates a client response.</p>${messages.map(m=>`<div class="row"><div><b>${PF.e(m.actor)}</b><p class="preserve-lines">${PF.e(m.body)}</p><span class="meta">${PF.e(PF.date(m.createdAt))}</span></div></div>`).join('')||PF.empty('No messages for this client.')}</section>`}
function onboarding(c){const rows=PF.w.onboarding.filter(x=>x.clientId===c.id);return `<section class="card" style="margin-top:18px"><div class="row"><h2>Onboarding checklist</h2>${PF.button('+ Add step','pf-add-onboarding',c.id)}</div><p class="meta">Shared checklist simulation, saved in this browser.</p>${rows.map(x=>`<div class="row"><span>${PF.e(x.title)}</span>${PF.button(x.done?'✓ Completed — reopen':'Mark complete','pf-toggle-onboarding',x.id).replace('data-id=',`data-client="${PF.e(c.id)}" data-id=`)}</div>`).join('')||PF.empty('Add a welcome step, content request, or kickoff action.')}</section>`}
PF.views.messages={title:'Messages',icon:'✉',group:'work',render(){if(!PF.client(state.client))state.client=PF.db.clients[0]?.id||'';const c=PF.client(state.client);return PF.heading('Client conversations','Agency and client preview actors share a browser-local conversation.')+select('clientId','Client',PF.clientOptions(),state.client,'data-pf-client="true"')+(c?thread(c)+onboarding(c):PF.empty('Create a client to start a conversation.'))}};
PF.actions['pf-add-message']=b=>{const clientId=scopedClient(b.dataset.id);PF.form('Write local message',select('actor','Preview actor',[['Agency','Agency'],['Client preview','Client preview']],'Agency')+area('body','Message (not delivered)','',true),f=>{scopedClient(clientId);if(!['Agency','Client preview'].includes(f.actor))throw Error('Choose a valid preview actor.');PF.w.messages.push({id:PF.id(),clientId,body:text(f.body,4000,true),actor:f.actor,createdAt:PF.now()});PF.log('message','Local message added','',clientId)})};
PF.actions['pf-add-onboarding']=b=>{const clientId=scopedClient(b.dataset.id);PF.form('New onboarding step',field('title','Step title','','text',true),f=>{scopedClient(clientId);PF.w.onboarding.push({id:PF.id(),clientId,title:text(f.title,500,true),done:false});PF.log('onboarding','Onboarding step added','',clientId)})};
PF.actions['pf-toggle-onboarding']=b=>PF.change(()=>{const x=PF.w.onboarding.find(x=>x.id===b.dataset.id&&x.clientId===b.dataset.client);if(!x)throw Error('Onboarding step no longer exists for this client.');scopedClient(x.clientId);x.done=!x.done;PF.log('onboarding','Onboarding step updated','',x.clientId)});
PF.onChange.push(event=>{const n=event.target;if(event.type!=='change'||!n?.dataset)return;if(n.dataset.pfFilter){const kind=n.dataset.pfFilter,key=n.dataset.key;if(state[kind]&&Object.hasOwn(state[kind],key)){state[kind][key]=n.value;PF.render()}}else if(n.dataset.pfClient){state.client=n.value;PF.render()}else if(n.dataset.pfMove){const kind=n.dataset.pfMove,id=n.dataset.id;PF.change(()=>{if(kind==='tasks'){const t=task(id);t.status=choice(n.value,statuses);PF.log('task','Task status changed',t.projectId)}else if(kind==='requests'){const r=request(id);PF.w.requestMeta[id]={...meta(id),status:choice(n.value,requestStatuses)};PF.log('request','Request status changed',meta(id).projectId,r.clientId)}})}});
PF.projectSections.push(p=>`<section style="margin-top:24px"><div class="row"><h2>Project tasks</h2>${PF.button('+ New task','pf-add-task',p.id)}</div>${PF.w.tasks.filter(t=>t.projectId===p.id).map(taskCard).join('')||PF.empty('No tasks linked to this project.')}<h2>Linked requests</h2>${PF.db.requests.filter(r=>meta(r.id).projectId===p.id&&r.clientId===p.clientId).map(requestCard).join('')||PF.empty('No requests linked to this project.')}</section>`);
PF.clientSections.push(c=>thread(c)+onboarding(c));
PF.validators.push((w,data)=>{const fail=()=>{throw Error('Saved operations data could not be validated.')};const str=(x,max=500,required=false)=>typeof x==='string'&&x.length<=max&&(!required||!!x.trim());const dateOK=x=>{try{due(x);return true}catch{return false}};const clientOK=id=>data.clients.some(c=>c.id===id);const projectOK=id=>id===''||data.projects.some(p=>p.id===id);const rows=(xs,check)=>Array.isArray(xs)&&xs.every(x=>x&&str(x.id,500,true)&&check(x))&&new Set(xs.map(x=>x.id)).size===xs.length;
if(!rows(w.tasks,t=>str(t.title,500,true)&&str(t.projectId)&&projectOK(t.projectId)&&Object.hasOwn(statuses,t.status)&&Object.hasOwn(priorities,t.priority)&&str(t.assignee)&&dateOK(t.due)&&rows(t.checklist,c=>str(c.text,500,true)&&typeof c.done==='boolean')&&t.checklist.length<=50))fail();
if(!w.requestMeta||typeof w.requestMeta!=='object'||Array.isArray(w.requestMeta))fail();Object.entries(w.requestMeta).forEach(([id,m])=>{const r=data.requests.find(r=>r.id===id);if(!r||!m||!Object.hasOwn(requestStatuses,m.status)||!Object.hasOwn(priorities,m.priority)||!str(m.assignee)||!dateOK(m.due)||!str(m.projectId)||!projectOK(m.projectId)||(m.projectId&&!data.projects.some(p=>p.id===m.projectId&&p.clientId===r.clientId)))fail()});
if(!rows(w.messages,m=>clientOK(m.clientId)&&str(m.body,4000,true)&&['Agency','Client preview'].includes(m.actor)&&str(m.createdAt)&&Number.isFinite(Date.parse(m.createdAt))))fail();
if(!rows(w.onboarding,x=>clientOK(x.clientId)&&str(x.title,500,true)&&typeof x.done==='boolean'))fail();
});
})(window.PF);
